export function youtubeId(value){try{const url=new URL(value);if(url.protocol!=='https:'||url.username||url.password||url.port)return null;let id;if(url.hostname==='youtu.be')id=url.pathname.slice(1).split('/')[0];else if(['youtube.com','www.youtube.com','m.youtube.com','youtube-nocookie.com','www.youtube-nocookie.com'].includes(url.hostname)){const path=url.pathname.split('/').filter(Boolean);id=path[0]==='watch'?url.searchParams.get('v'):['embed','shorts','live'].includes(path[0])?path[1]:null}return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:null}catch{return null}}
export function youtubeEmbed(id){if(!/^[A-Za-z0-9_-]{11}$/.test(id))throw Error('Vídeo do YouTube inválido.');return 'https://www.youtube-nocookie.com/embed/'+id+'?rel=0&playsinline=1'}
